//! S4-T1 ruling 2: an index written at commit 292cb568 (the commit the
//! consumer app pins; phones hold indexes in its format) still opens,
//! answers every read operation, and takes an `apply_changes` generation.
//! The fixture is `tests/fixtures/index-292cb568/`, regenerated by
//! `tests/fixtures/gen_index_292cb568.sh` (`fixtures/family-folder/home`
//! through that commit's `searchd index`): manifest v2 without
//! `flag_xxh3_sections`, every section FNV-1a 64.
const std = @import("std");
const apply = @import("apply.zig");
const checksum = @import("checksum.zig");
const engine_module = @import("engine.zig");
const hybrid = @import("hybrid.zig");
const lexical_segment = @import("lexical_segment.zig");
const manifest = @import("manifest.zig");
const publication = @import("publication.zig");
const segment = @import("segment.zig");
const service_module = @import("service.zig");
const snapshot_open = @import("snapshot_open.zig");
const source = @import("source.zig");

const io = std.testing.io;
const fixture = "../tests/fixtures/index-292cb568";
const files = [_][]const u8{ "MANIFEST", "INDEX-STATE.json", "documents-1.hybseg", "lexical-1.hyblex", "source-1.hybsrc" };

/// A writable copy of the fixture (the open and `apply_changes` may write).
fn copyFixture(a: std.mem.Allocator, out: std.Io.Dir) !void {
    var from = try std.Io.Dir.cwd().openDir(io, fixture, .{});
    defer from.close(io);
    for (files) |name| try out.writeFile(io, .{ .sub_path = name, .data = try from.readFileAlloc(io, name, a, .unlimited) });
}

fn checkReads(a: std.mem.Allocator, dir: std.Io.Dir) !void {
    const opened = try snapshot_open.openScoped(a, io, dir);
    defer opened.folder.close();
    const scoped = service_module.ScopedService{ .service = .{ .engine = opened.engine, .folder = opened.folder } };
    const status = try scoped.indexStatus(a, .{});
    try std.testing.expect(status.has_source);
    try std.testing.expectEqualStrings("unverified", status.source);
    try std.testing.expect(status.files >= 12);

    const found = (try scoped.find(a, .{ .query = "frogspawn" }, .{})).ok;
    try std.testing.expectEqual(@as(usize, 1), found.hits.len);
    try std.testing.expectEqualStrings("garden.md", found.hits[0].path);
    const phrase = (try scoped.find(a, .{ .query = "family of snails", .mode = .phrase }, .{})).ok;
    try std.testing.expectEqual(@as(usize, 1), phrase.hits.len);

    const span = (try scoped.readSpan(a, .{}, "r-legacy", "garden.md", 1, 1, 0)).ok;
    try std.testing.expectEqualStrings("# Garden\n", span.text);
    try std.testing.expectEqualStrings("verified", (try scoped.indexStatus(a, .{})).source);

    const outline = (try scoped.outline(a, .{}, "r-legacy", "garden.md")).ok;
    try std.testing.expect(outline.markdown != null);
    try std.testing.expect(outline.markdown.?.headings.len >= 3);

    const listed = try scoped.listFiles(a, .{}, "r-legacy", null);
    try std.testing.expect(listed.len >= 12);

    const evidence = try scoped.searchKnowledge(a, "hedgehogs pond", &.{}, .{ .retrieval_mode = .lexical, .top_k = 4 }, .{}, try a.alloc(hybrid.Result, 4), try a.alloc(engine_module.Evidence, 4), null);
    try std.testing.expect(evidence.len >= 1);
    try std.testing.expectEqualStrings("garden.md", evidence[0].path);
}

test "S4-T1: the 292cb568 fixture is the pre-v2.1 format (FNV-1a sections, no flag 4)" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var dir = try std.Io.Dir.cwd().openDir(io, fixture, .{});
    defer dir.close(io);
    const metadata = try manifest.decode(try dir.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    try std.testing.expectEqual(manifest.version_v2, metadata.format_version);
    try std.testing.expect(!metadata.xxh3_sections);
    try std.testing.expectEqual(checksum.Kind.fnv1a64, (try segment.inspect(try dir.readFileAlloc(io, metadata.documents_file, a, .unlimited))).checksum_kind);
    try std.testing.expectEqual(checksum.Kind.fnv1a64, (try lexical_segment.inspect(try dir.readFileAlloc(io, metadata.lexical_file, a, .unlimited))).checksum_kind);
    try std.testing.expectEqual(checksum.Kind.fnv1a64, (try source.inspect(try dir.readFileAlloc(io, metadata.source_file, a, .unlimited))).checksum_kind);
}

test "S4-T1: an index written at 292cb568 opens and answers find, read_span, outline, list_files and search_knowledge" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try copyFixture(a, tmp.dir);
    try checkReads(a, tmp.dir);
    // The eager open (the CLI's unscoped path) reads it too.
    _ = try snapshot_open.open(a, io, tmp.dir);
}

test "S4-T1: apply_changes over a 292cb568 index publishes a v2.2 generation (XXH3 sections, no filename sections) that reads the same" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try copyFixture(a, tmp.dir);
    const request =
        \\{"changes":[{"op":"add","root_id":"r-legacy","path":"shed.txt","content_base64":"VGhlIHNoZWQgbmVlZHMgYSBuZXcgbG9jay4K"}]}
    ;
    const report = switch (try apply.applyChanges(a, io, tmp.dir, request, .{})) {
        .ok => |r| r,
        .failed => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(u64, 2), report.generation);
    try std.testing.expectEqual(@as(usize, 1), report.added);
    const metadata = try manifest.decode(try tmp.dir.readFileAlloc(io, publication.current_manifest_file, a, .unlimited));
    try std.testing.expect(metadata.xxh3_sections);
    try std.testing.expectEqual(checksum.Kind.xxh3_64, (try source.inspect(try tmp.dir.readFileAlloc(io, metadata.source_file, a, .unlimited))).checksum_kind);
    // S4-T2 R7: the upgrade never turns on the filename channel (flag 8):
    // an omitted setting keeps the directory's, and a 292cb568 index has
    // none. It does bind its recovery-state section (flag 16, v2.2).
    try std.testing.expect(metadata.filename == null);
    try std.testing.expectEqualStrings("state-2.hybstate", metadata.state.?.file);
    var listing = tmp.dir.iterate();
    while (try listing.next(io)) |entry| {
        try std.testing.expect(!std.mem.startsWith(u8, entry.name, "filename"));
    }
    try checkReads(a, tmp.dir);
    const opened = try snapshot_open.openScoped(a, io, tmp.dir);
    defer opened.folder.close();
    const scoped = service_module.ScopedService{ .service = .{ .engine = opened.engine, .folder = opened.folder } };
    try std.testing.expectEqual(@as(usize, 1), (try scoped.find(a, .{ .query = "lock" }, .{})).ok.hits.len);
}

test "S5-T2: a 292cb568 index gets the title field by the derive, at its first content query and not at the open" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try copyFixture(a, tmp.dir);
    const opened = try snapshot_open.openScoped(a, io, tmp.dir);
    defer opened.folder.close();
    try std.testing.expect(!opened.folder.titleDerived());
    const scoped = service_module.ScopedService{ .service = .{ .engine = opened.engine, .folder = opened.folder } };
    const status = try scoped.indexStatus(a, .{});
    const evidence = try scoped.searchKnowledge(a, "garden", &.{}, .{ .retrieval_mode = .lexical, .top_k = 4 }, .{}, try a.alloc(hybrid.Result, 4), try a.alloc(engine_module.Evidence, 4), null);
    try std.testing.expect(opened.folder.titleDerived());
    const field = try opened.folder.titleField();
    // One title document per file with a chunk (an empty file has none).
    var paths: usize = 0;
    for (opened.engine.documents, 0..) |document, i| {
        if (i == 0 or !std.mem.eql(u8, opened.engine.documents[i - 1].path, document.path)) paths += 1;
    }
    try std.testing.expectEqual(paths, field.files.len);
    try std.testing.expect(field.files.len <= status.files);
    try std.testing.expect(evidence.len >= 1);
    try std.testing.expectEqualStrings("garden.md", evidence[0].path);
    // The file's name took its part, inside the lexical score.
    const part = evidence[0].title_score orelse return error.TestUnexpectedResult;
    try std.testing.expect(part > 0 and part < evidence[0].lexical_score);
}

test "S5-T3: a 292cb568 index opens and expands a misspelt word (fuzzy-v1 needs no rebuild)" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try copyFixture(a, tmp.dir);
    const opened = try snapshot_open.openScoped(a, io, tmp.dir);
    defer opened.folder.close();
    const options = hybrid.SearchOptions{ .retrieval_mode = .lexical, .top_k = 4 };
    try std.testing.expect(opened.engine.fuzzyApplies(.content, options));
    const scoped = service_module.ScopedService{ .service = .{ .engine = opened.engine, .folder = opened.folder } };
    // `gardne` (6 code points) is held by no chunk and no name; `garden` is one swap away.
    const evidence = try scoped.searchKnowledge(a, "gardne", &.{}, options, .{}, try a.alloc(hybrid.Result, 4), try a.alloc(engine_module.Evidence, 4), null);
    try std.testing.expect(evidence.len >= 1);
    try std.testing.expectEqualStrings("garden.md", evidence[0].path);
    // With fuzzy-v1 off the same word finds nothing, as before S5-T3.
    var off = options;
    off.fuzzy = false;
    const none = try scoped.searchKnowledge(a, "gardne", &.{}, off, .{}, try a.alloc(hybrid.Result, 4), try a.alloc(engine_module.Evidence, 4), null);
    try std.testing.expectEqual(@as(usize, 0), none.len);
}

test "S5-T4: a 292cb568 index opens and groups a plural with its singular (fold-groups-v1 needs no rebuild)" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try copyFixture(a, tmp.dir);
    const opened = try snapshot_open.openScoped(a, io, tmp.dir);
    defer opened.folder.close();
    const options = hybrid.SearchOptions{ .retrieval_mode = .lexical, .top_k = 4 };
    try std.testing.expect(opened.engine.foldApplies(.content, options));
    const scoped = service_module.ScopedService{ .service = .{ .engine = opened.engine, .folder = opened.folder } };
    // `frog` is held by no chunk and no name; `frogs` (garden.md) shares its key.
    var trace = hybrid.Trace{ .allocator = a, .io = io };
    const evidence = try scoped.searchKnowledge(a, "frog", &.{}, options, .{}, try a.alloc(hybrid.Result, 4), try a.alloc(engine_module.Evidence, 4), &trace);
    try std.testing.expect(evidence.len >= 1);
    try std.testing.expectEqualStrings("garden.md", evidence[0].path);
    try std.testing.expectEqual(@as(usize, 1), trace.grouped.items.len);
    try std.testing.expectEqualStrings("frogs", trace.grouped.items[0].members[0]);
    // With fold-groups-v1 off the same word finds nothing, as before S5-T4.
    var off = options;
    off.fold = false;
    const none = try scoped.searchKnowledge(a, "frog", &.{}, off, .{}, try a.alloc(hybrid.Result, 4), try a.alloc(engine_module.Evidence, 4), null);
    try std.testing.expectEqual(@as(usize, 0), none.len);
}

test "S5-T5: a 292cb568 index opens and groups a word with its verb forms (fold-groups-v2 needs no rebuild)" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    var tmp = std.testing.tmpDir(.{ .iterate = true });
    defer tmp.cleanup();
    try copyFixture(a, tmp.dir);
    const opened = try snapshot_open.openScoped(a, io, tmp.dir);
    defer opened.folder.close();
    const options = hybrid.SearchOptions{ .retrieval_mode = .lexical, .top_k = 4 };
    const scoped = service_module.ScopedService{ .service = .{ .engine = opened.engine, .folder = opened.folder } };
    // `baked` is held by no chunk and no name; R reaches `bake` and `baking`,
    // each at 1.0, and fuzzy-v1 does not also run on it.
    var trace = hybrid.Trace{ .allocator = a, .io = io };
    const evidence = try scoped.searchKnowledge(a, "baked", &.{}, options, .{}, try a.alloc(hybrid.Result, 4), try a.alloc(engine_module.Evidence, 4), &trace);
    try std.testing.expect(evidence.len >= 1);
    try std.testing.expectEqual(@as(usize, 1), trace.grouped.items.len);
    try std.testing.expectEqual(@as(usize, 2), trace.grouped.items[0].members.len);
    try std.testing.expectEqual(@as(usize, 0), trace.expanded.items.len);
    for (trace.grouped.items[0].members) |m| try std.testing.expect(std.mem.eql(u8, m, "bake") or std.mem.eql(u8, m, "baking"));
}
